import numpy as np
from numba import njit

@njit
def pairwise_l2(x):
    n = x.shape[0]
    out = np.empty((n, n))
    for i in range(n):
        for j in range(n):
            out[i, j] = np.sqrt(((x[i] - x[j]) ** 2).sum())
    return out

print(pairwise_l2(np.random.rand(200, 8)).shape)
